    84→func checkValidatorSlashable(activationEpoch, withdrawableEpoch primitives.Epoch, slashed bool, epoch primitives.Epoch) bool {
    85→	active := activationEpoch <= epoch
    86→	beforeWithdrawable := epoch < withdrawableEpoch
    87→	return beforeWithdrawable && active && !slashed
