   276→// cachedProposerIndexAtSlot returns the proposer index at the given slot from
   277→// the cache at the given root key.
   278→func cachedProposerIndexAtSlot(slot primitives.Slot, root [32]byte) (primitives.ValidatorIndex, error) {
   279→	proposerIndices, has := proposerIndicesCache.ProposerIndices(slots.ToEpoch(slot), root)
   280→	if !has {
   281→		return 0, errProposerIndexMiss
   282→	}
   283→	if len(proposerIndices) != int(params.BeaconConfig().SlotsPerEpoch) {
